0,"Design and implement a code snippet that handles caching for an audio player application. The code should first verify if an audio file has been played recently. If not, it should clear the cached file and set a placeholder for the default audio path. Subsequently, the code should extract metadata information from a JSON file within the cache directory and store it in a suitable data structure for later use.",276,,"[""```python
import os
import json
from datetime import datetime, timedelta
from collections import defaultdict

CACHE_DIR = 'cache'
DEFAULT_AUDIO_PATH = 'default_audio.mp3'
RECENTLY_PLAYED_DURATION = timedelta(days=1)

def clear_cache():
    if os.path.exists(CACHE_DIR):
        for file in os.listdir(CACHE_DIR):
            file_path = os.path.join(CACHE_DIR, file)
            os.remove(file_path)

def get_cached_metadata(audio_path):
    cached_files = {f: os.path.join(CACHE_DIR, f) for f in os.listdir(CACHE_DIR)}
    if audio_path not in cached_files:
        return None
    metadata_file = cached_files[audio_path] + '.metadata.json'
    if not os.path.exists(metadata_file):
        return None
    with open(metadata_file) as f:
        metadata = json.load(f)
    return metadata

def store_metadata(audio_path, metadata):
    cached_files = {f: os.path.join(CACHE_DIR, f) for f in os.listdir(CACHE_DIR)}
    if audio_path not in cached_files:
        cached_files[audio_path] = DEFAULT_AUDIO_PATH
    metadata_file = cached_files[audio_path] + '.metadata.json'
    with open(metadata_file, 'w') as f:
        json.dump(metadata, f)

def is_recently_played(audio_path):
    if not os.path.exists(CACHE_DIR):
        return False
    for file in os.listdir(CACHE_DIR):
        file_path = os.path.join(CACHE_DIR, file)
        if audio_path == file or audio_path == DEFAULT_AUDIO_PATH:
            cached_file_time = datetime.fromtimestamp(os.path.getmtime(file_path))
            recent_play = (datetime.now() - cached_file_time) < RECENTLY_PLAYED_DURATION
            if recent_play:
                return True
    return False

def main():
    # Initialize cache directory and clear it if needed
    if not os.path.exists(CACHE_DIR):
        os.makedirs(CACHE_DIR)
    clear_cache()

    # Load metadata for default audio file (if exists)
    default_metadata = get_cached_metadata(DEFAULT_AUDIO_PATH)

