# Instantiate FileProcessor object and call main method",327,,"[' ```python
import os
import re

class FileProcessor:
    def __init__(self, filename):
        self.filename = filename

    def read_file(self):
        try:
            with open(self.filename, 'r') as file:
                lines = file.readlines()
            return lines
        except FileNotFoundError:
            return f""Error: File '{self.filename}' not found.""
        except Exception as e:
            return f""An error occurred while reading the file: {str(e)}""

    def sort_lines(self, lines):
        try:
            sorted_lines = sorted(lines)
            return sorted_lines
        except TypeError:
            return ""Error: Invalid input type for sorting.""
        except Exception as e:
            return f""An error occurred during sorting: {str(e)}""

    def extract_sequence_number(self, sorted_lines):
        try:
            last_line = sorted_lines[-1]
            match = re.search(r'(\d+)$', last_line)
            if match is not None:
                sequence_number = int(match.group(1))
                return sequence_number
            else:
                raise ValueError(""No valid sequence number found."")
        except IndexError as e:
            return ""Error: Last line does not contain a valid sequence number.""
        except ValueError as e:
            return str(e)
        except Exception as e:
            return f""An error occurred while extracting the sequence number: {str(e)}""

def main():
    filename = ""example.txt""
    processor = FileProcessor(filename)

    result = processor.read_file()

    if isinstance(result, str) and result.startswith(""Error""):
        print(result)
    else:
        lines = processor.sort_lines(processor.read_file())

        if isinstance(lines, str) and lines.startswith(""Error""):
            print(lines)
        else:
            sequence_number = processor.extract_sequence_number(lines)

            if isinstance(sequence_number, str) and sequence_number.startswith(""Error""):
                print(sequence_number)
            else:
                print(f""The sequence number is: {sequence_number}"")
