import re
def enhanced_sort_file(input_file, output_file):
    try:
        with open(input_file, 'r') as file:
            lines = sorted(file.readlines())

            if not lines:
                raise ValueError(""Input file is empty"")

            last_line = lines[-1].strip()
            sequence_number = extract_sequence_number(last_line)

            with open(output_file, 'w') as out_file:
                for line in lines[:-1]:
                    out_file.write(line)
                out_file.write(f""Sequence Number: {sequence_number}\n"")

                if sequence_number.isdigit():
                    print(f""Sequence Number: {sequence_number}"")
                else:
                    print(""No valid sequence number found in the last line."")

    except FileNotFoundError as e:
        print(f""Error: File not found - {e}"")

    except ValueError as e:
        print(f""Error: {e}"")

    except IOError as e:
        print(f""Error: File I/O - {e}"")

def extract_sequence_number(line):
   pattern = r""\d{4}-\d{2}-\d{2}""
   match = re.search(pattern, line)

   if match:
       return match.group(0)
   else:
       raise ValueError(""No valid sequence number found in the provided string"")

# Usage example
enhanced_sort_file('input.txt', 'output.txt')
