import time
from sets import Set

def count_unique_numbers(lst):
    start = time.time()
    unique_nums = set()
    for num in [int(''.join(map(str, sorted(lst[i:]))) for i in range(len(lst))]:
        unique_nums.add(num)
    end = time.time()
    return len(unique_nums), round((end - start) * 1000)
```

