3,"Create a Python function that generates an array of `SensorData` objects. Each object should contain fields for temperature, humidity, and the timestamp of the reading. The function should populate the array with randomly generated sensor data within specified valid ranges, ensuring that timestamps are in ascending order. Implement error checking to validate the generated temperature and humidity values, and use Python's standard library functions for random number generation.",680,,"['```python
import datetime as dt
import random

class SensorData:
    def __init__(self, timestamp, temperature, humidity):
        self.timestamp = timestamp
        self.temperature = temperature
        self.humidity = humidity

def generate_sensor_data(start_time, end_time, num_of_samples, min_temp, max_temp, min_humidity, max_humidity):
    time_diff = (end_time - start_time).total_seconds() / num_of_samples
    timestamps = [start_time + dt.timedelta(seconds=i * time_diff) for i in range(num_of_samples)]

    sensor_data_list = []
    for timestamp in timestamps:
        temperature = random.uniform(min_temp, max_temp)
        humidity = random.uniform(min_humidity, max_humidity)

        if temperature > max_temp or temperature < min_temp:
            raise ValueError(""Generated temperature is out of range."")
        if humidity > max_humidity or humidity < min_humidity:
            raise ValueError(""Generated humidity is out of range."")

        sensor_data = SensorData(timestamp, temperature, humidity)
        sensor_data_list.append(sensor_data)

    return sorted(sensor_data_list, key=lambda x: x.timestamp)
