0,"Create a Python script for handling a library book inventory. Define a Book class with title, author, and publication year attributes. Implement methods to add books to the inventory, display book details, and remove books from the collection. Ensure memory is properly managed at the end of the program execution.",338,,"['```python
class Book:
    def __init__(self, title, author, publication_year):
        self.title = title
        self.author = author
        self.publication_year = publication_year

    def display_details(self):
        return f""Title: {self.title}, Author: {self.author}, Publication Year: {self.publication_year}""

    def __del__(self):
        print(""Book object deleted from memory."")

class LibraryInventory:
    def __init__(self):
        self.books = []

    def add_book(self, book):
        self.books.append(book)

    def display_inventory(self):
        for book in self.books:
            print(book.display_details())

    def remove_book(self, title):
        self.books = [b for b in self.books if b.title != title]

# Example usage
library = LibraryInventory()

book1 = Book(""The Catcher in the Rye"", ""J.D. Salinger"", 1951)
book2 = Book(""To Kill a Mockingbird"", ""Harper Lee"", 1960)

library.add_book(book1)
library.add_book(book2)
library.display_inventory()

# Remove a book
library.remove_book(""The Catcher in the Rye"")
library.display_inventory()
```
