1,"Develop a Python function named `factorial_calculator` that accepts an integer input and outputs its factorial, prefixed with ""Factorial:"". The function must validate the input, rejecting negative numbers and raising custom exceptions for calculation issues. Compose unit tests for boundary conditions and performance assessments.",327,,"[' Here is the Python code for the `factorial_calculator` function and its corresponding unit tests:

```python
class CalculationIssue(Exception):
    pass

def factorial_calculator(n):
    if not isinstance(n, int) or n < 0:
        raise ValueError(""Factorial input must be a non-negative integer."")

    result = 1
    for i in range(2, n + 1):
        result *= i
    return f""Factorial: {result}""

import unittest

class TestFactorialCalculator(unittest.TestCase):

    def test_valid_input(self):
        self.assertEqual(factorial_calculator(5), ""Factorial: 120"")
        self.assertEqual(factorial_calculator(10), ""Factorial: 3628800"")
        self.assertEqual(factorial_calculator(42), ""Factorial: 87178291200"")

    def test_negative_input(self):
        with self.assertRaises(ValueError):
            factorial_calculator(-5)
        with self.assertRaises(ValueError):
            factorial_calculator(-1)

    def test_large_input(self):
        with self.assertRaises(CalculationIssue):
            factorial_calculator(100000)  # or any large number that causes overflow

if __name__ == ""__main__"":
    unittest.main()
```']",0,[0],[],True,0,0,0,

