from __future__ import annotations
import random
from abc import ABC, abstractmethod

class AbstractVertex(ABC):
    @abstractmethod
    def save(self):
        pass

class AbstractEdge(ABC):
    @abstractmethod
    def save(self):
        pass

def create_vertex_class():
    return type('Vertex', (AbstractVertex,), {})

def create_edge_class():
    return type('Edge', (AbstractEdge,), {'source': None, 'target': None, 'property': 0})

class GraphDatabase:
    def __init__(self):
        self.vertices_added = 0
        self.edges_added = 0

    def randomize_graph(self, vertices_to_add=100, edges_to_add=100):
        Vertex = create_vertex_class()
        Edge = create_edge_class()

        for _ in range(vertices_to_add):
            vertex = Vertex()
            vertex.random_property = random.uniform(0, 1)
            vertex.save()
            self.vertices_added += 1

        for _ in range(edges_to_add):
            source_vertex = Vertex.objects.order_by('?').first()
            target_vertex = Vertex.objects.order_by('?').first()
            edge = Edge(source=source_vertex, target=target_vertex, property=random.uniform(0, 1))
            edge.save()
            self.edges_added += 1

def process_file(filename=None):
    if filename is None:
        filename = input(""Enter the name of the file: "")

    try:
        with open(filename) as file:
            lines = [line.strip() for line in file]
            processed_lines_count = len(lines)
            print(f""Processed {processed_lines_count} lines."")
            return processed_lines_count

    except FileNotFoundError:
        print(f""Error: File '{filename}' not found."")
```
