import csv
from statistics import mean, stdev, median, mode

def calculate_stats(file_path):
    with open(file_path) as f:
        reader = csv.reader(f)
        header = next(reader)  # Skip the header row

        column_stats = {}
        for row in reader:
            for i, value in enumerate(row):
