0,"Design and implement a program that simulates a simplified banking system. The program should allow users to create accounts, deposit and withdraw funds, and check their balance. Each account should have an account number, owner's name, and current balance. Implement functions for account creation, deposit, withdrawal, and balance checking. Include error handling for insufficient funds and invalid transactions. The program should also have a main menu to guide the user through the available options.",680,,"['```python
class Account:
    def __init__(self, account_number, owner_name, balance=0):
        self.account_number = account_number
        self.owner_name = owner_name
        self.balance = balance

    def deposit(self, amount):
        if amount <= 0:
            print(""Invalid deposit amount."")
            return
        self.balance += amount

    def withdraw(self, amount):
        if amount > self.balance:
            print(""Insufficient funds."")
            return
        self.balance -= amount

    def check_balance(self):
        return self.balance

def create_account():
    account_number = input(""Enter account number: "")
    owner_name = input(""Enter owner's name: "")
    new_account = Account(account_number, owner_name)
    return new_account

def main_menu():
    print(""\nBanking System Menu"")
    print(""1. Create Account"")
    print(""2. Deposit Funds"")
    print(""3. Withdraw Funds"")
    print(""4. Check Balance"")
    print(""5. Exit"")

def main():
    accounts = {}
    while True:
        main_menu()
        choice = int(input(""Enter your choice: ""))
        if choice == 1:
            account = create_account()
            accounts[account.account_number] = account
        elif choice == 2:
            account_number = input(""Enter account number: "")
            if account_number not in accounts:
                print(""Account not found."")
                continue
            amount = float(input(""Enter deposit amount: ""))
            accounts[account_number].deposit(amount)
        elif choice == 3:
            account_number = input(""Enter account number: "")
            if account_number not in accounts:
                print(""Account not found."")
                continue
            amount = float(input(""Enter withdrawal amount: ""))
            accounts[account_number].withdraw(amount)
        elif choice == 4:
            account_number = input(""Enter account number: "")
            if account_number not in accounts:
                print(""Account not found."")
                continue
            balance = accounts[account_number].check_balance()
            print(f""Balance for {accounts[account_number].owner_name}: ${balance}"")
        elif choice == 5:
            break
        else:
            print(""Invalid choice. Please try again."")

if __name__ == ""__main__"":
    main()
