1,"Create a Python function that reads a log file, parses timestamps from each line, calculates the difference between consecutive timestamps, and returns the average time interval between them. Ensure to handle any potential exceptions, such as missing timestamps or file reading errors, gracefully.",94,,"['```python
import re
import time
from datetime import datetime

def calculate_avg_interval(log_file):
    try:
        with open(log_file, 'r') as file:
            intervals = []
            prev_timestamp = None
            for line in file:
                timestamp_match = re.search(r'\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}', line)
                if timestamp_match:
                    current_timestamp = datetime.strptime(timestamp_match.group(), '%Y-%m-%d %H:%M:%S')
                    if prev_timestamp:
                        interval = (current_timestamp - prev_timestamp).total_seconds()
                        intervals.append(interval)
                    prev_timestamp = current_timestamp
            if intervals and len(intervals) > 1:
                avg_interval = sum(intervals) / len(intervals)
                return avg_interval
            else:
                raise Exception(""Not enough valid timestamps to calculate average interval."")
    except FileNotFoundError:
        return ""Log file not found.""
    except ValueError:
        return ""Invalid timestamp format in the log file.""
