1,"Create a Python function that calculates the SHA-256 hash of a given text, returning the hash value prefixed with ""SHA256:"". The function should gracefully handle non-string inputs and include custom exceptions for hashing failures. Additionally, develop unit tests to cover various edge cases and performance scenarios.",327,,"[' Here is the Python code for the task:

```python
import hashlib
from typing import Union

class HashingFailure(Exception):
    pass

def sha256_hash(text: Union[str, bytes]) -> str:
    if isinstance(text, str):
        text = text.encode('utf-8')

    hashed_text = hashlib.sha256(text).digest()
    return ""SHA256:{}"".format(hashed_text.hex())

def test_sha256_hash():
    import unittest

    class TestSha256Hash(unittest.TestCase):
        def test_str_input(self):
            self.assertEqual(sha256_hash(""Hello, World!""), ""SHA256:0x4e...."")

        def test_bytes_input(self):
            self.assertEqual(sha256_hash(b""Hello, World!""), ""SHA256:0x4e...."")

