import time

def concat_distinct(numbers):
    start = time.time()
    distinct_concatenations = set()
    for i in range(len(numbers)):
        for j in range(i, len(numbers)):
            key = ''.join(map(str, numbers[i:j]))
            if key not in distinct_concatenations:
                distinct_concatenations.add(key)
    elapsed = (time.time() - start) * 1000
    return len(distinct_concatenations), elapsed
