    ip_set = set()
    sockets = []

    try:
        data = urlopen('https://api.ipify.org').read().decode('utf-8').split('\n')[0]
        hostname, _ = data.split('.')[:2] + ('.' * (5 - len(data.split('.'))))
    except Exception as e:
        return f'Error occurred while fetching IP address: {str(e)}', [], None

    current_day = datetime.datetime.now().weekday()
    broadcast_flag = not (current_day >= 5 or current_day == 0)

    bytes_received = random.randint(10, 100) * (60 * 60)

    ip_address = f'{hostname}-{random.randint(1, 9999)}'
    socket_entity = {'ip': ip_address, 'broadcast_enabled': broadcast_flag, 'total_bytes_received': bytes_received}

    if ip_set.add(ip_address):
        sockets.append(socket_entity)
    else:
        return f'Error: Duplicate IP address found.', sockets, None

    for _ in range(limit - 1):
        try:
            generate_sockets(1)[1].append(socket_entity)
            break
        except IndexError:
            pass

    total_bytes = sum([socket['total_bytes_received'] for socket in sockets])
    average_bytes = total_bytes / limit if len(sockets) > 0 else None

    return f'Generated {len(sockets)} SOCKET_TYPE_U entities.', sockets, (average_bytes if average_bytes is not None else None)

print(generate_sockets(10))
```

This code fetches the current IP address using an external API, generates SOCKET_TYPE_U entities based on the given requirements and options, and calculates the average total bytes received per entity. The function handles potential errors related to fetching the IP address and duplicate IP addresses in the generated list.""]",0,[0],[],True,0,0,0,

