The implementation should cover error handling for potential issues like invalid input parameters or database access failures.",680,,"[' Here's a pseudo-code that outlines the required functionality:

```python
import random
import collections.abc as abc
from typing import List, Dict, Union, Tuple

class NamespaceDatabase:
    def __init__(self):
        self._records = {}

    def add_record(self, domain: str) -> None:
        if domain in self._records:
            raise ValueError(""Domain already registered."")
        else:
            self._records[domain] = []

    def get_registered_domains(self) -> List[str]:
        return list(self._records.keys())

class NAPTRRecord:
    def __init__(self, domain: str, service_type: str, preference: int, priority: int, port: int):
        self.domain = domain
        self.service_type = service_type
        self.preference = preference
        self.priority = priority
        self.port = port

class ZoneConfig:
    def __init__(self, min_port: int, max_port: int):
        self.min_port = min_port
        self.max_port = max_port

def create_naptr_records(zone_config: ZoneConfig, num_records: int, registered_domains: List[str]) -> List[NAPTRRecord]:
    if not zone_config or num_records <= 0:
        raise ValueError(""Invalid input parameters."")

    db = NamespaceDatabase()
    for domain in registered_domains:
        db.add_record(domain)

    records = []
    service_types = set()

    while len(records) < num_records:
        domain = f""{random_string(10)}-{random.randint(1, 9999)}.example.com""

        if domain in registered_domains:
            continue

        service_type = random_string(5)

        if service_type in service_types:
            continue

        service_types.add(service_type)

        preference, priority = random.randint(1, 16384), random.randint(1, 256)
        port = random.randint(zone_config.min_port, zone_config.max_port)

        record = NAPTRRecord(domain, service_type, preference, priority, port)
        records.append(record)

    return records

def random_string(length: int) -> str:
    return ''.join(random.choices('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-', k=length))
```

