}

impl CompilationContext {
    fn new() -> Self {
        Self {
            start_time: Instant :: now(),
            exit_code: Arc :: new ( AtomicUsize :: new ( 0 )),
            errors: Vec::new(),
            warnings: Vec::new(),
        }
    }

    fn elapsed(&self) -> Duration {
        self.start_time.elapsed()
    }

    fn get_exit_code(&self) -> usize {
