def prime_sum(n):
    primes = [2]
    sqrt_n = int(n ** 0.5)

    for i in range(3, n + 1, 2):
        is_prime = True
        for j in primes:
            if i % j == 0 or j > sqrt_n:
                break
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(i)

    return primes, sum(primes)
