import base64
from Cryptodome.Cipher import AES
from Cryptodome.Random import get_random_bytes

class UserProductReview:
    def __init__(self, user_id, product_id, review):
        self.user_id = user_id
        self.product_id = product_id
        self.review = review

    @staticmethod
    def encrypt(review_struct):
        key = get_random_bytes(32)
        cipher = AES.new(key, AES.MODE_ECB)
        encrypted_data = base64.b64encode(cipher.encrypt(review_struct.serialize()))
        return dict(encrypted_user_id=base64.b64encode(key + review_struct.user_id), encrypted_review=encrypted_data)

    @staticmethod
    def deserialize(data):
        key = base64.b64decode(data['encrypted_user_id'])[:32]
        cipher = AES.new(key, AES.MODE_ECB)
        decrypted_data = cipher.decrypt(base64.b64decode(data['encrypted_review']))
        return UserProductReview(*pickle.loads(decrypted_data))

