 attempting to use both MD5 and SHA-256 simultaneously should raise a ValueError due to conflicting hashing options.",328,,"['```python
import hashlib
import os
from typing import List, Dict, Union

def compute_hash(files: List[str], algorithm: Union['md5', 'sha256'], chunk_size=65536) -> Dict[str, str]:
    if algorithm not in ['md5', 'sha256']:
        raise ValueError(""Invalid hashing algorithm. Supported options are 'md5' and 'sha256'."")

    result = {}

    for file in files:
        try:
            with open(file, ""rb"") as f:
                if algorithm == 'md5':
                    hasher = hashlib.md5()
                elif algorithm == 'sha256':
                    hasher = hashlib.sha256()

                while True:
                    data = f.read(chunk_size)
                    if not data:
                        break
                    hasher.update(data)

                result[file] = hasher.hexdigest()
        except Exception as e:
            print(f""Error reading file {file}: {e}"")

    return result
