import random
import uuid
from hashlib import sha256
import copy

class Notification:
    def __init__(self, id, timestamp, category):
        self.id = id
        self.timestamp = timestamp
        self.category = category
        self.hash_value = self._compute_hash(id)

    @staticmethod
    def _compute_hash(data):
        return sha256(data.encode()).hexdigest()

def generate_notifications(N):
    notifications = []
    while len(notifications) < N:
        id = str(uuid.uuid4().hex).upper()
        if id not in [notification.id for notification in notifications] and len(notifications) + 1 <= N:
            timestamp = random.randint(0, 9999)
            category = random.choice(['INFO', 'WARNING', 'ERROR'])
            new_notification = Notification(id, timestamp, category)
            notifications.append(new_notification)
    return notifications
