4,"Write a Python script that reads configuration files from a specified directory, parses them, and generates summary statistics about the configurations. The script should accept command line arguments including --help for displaying usage information, -d directory_path to specify the directory containing the configuration files, and -o output_file_path to specify the output file where summary statistics will be written. Utilize standard library functions for file I/O and parsing, and provide clear error messages for invalid input or missing files.",121,,"['```python
import argparse
import os
import yaml
from typing import Dict, Any

def read_yaml(filepath: str) -> Dict[str, Any]:
    with open(filepath, 'r') as file:
        return yaml.safe_load(file)

def parse_stats(configs: Dict[str, Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
    stats = {}
    for name, config in configs.items():
        for key, value in config.items():
            if key not in stats:
                stats[key] = {'count': 1, 'sum': value}
            else:
                stats[key]['count'] += 1
                stats[key]['sum'] += value
    return {k: v for k, v in stats.items() if v['count'] > 0}

def main():
    parser = argparse.ArgumentParser(description=""Generate summary statistics about configuration files."")
    parser.add_argument('-d', '--directory', required=True, help=""Path to the directory containing configuration files."")
    parser.add_argument('-o', '--output', default='summary.yaml', help=""Path to output file for summary statistics."")
    args = parser.parse_args()

    if not os.path.exists(args.directory):
        print(f""Error: Directory '{args.directory}' does not exist."")
        exit(1)

    configs = {}
    for root, dirs, files in os.walk(args.directory):
        for file in files:
            if file.endswith('.yaml'):
                config_path = os.path.join(root, file)
                try:
                    config = read_yaml(config_path)
                    configs[os.path.relpath(config_path, args.directory)] = config
                except Exception as e:
                    print(f""Error reading configuration file '{config_path}': {e}"")

    stats = parse_stats(configs)
    with open(args.output, 'w') as outfile:
        yaml.dump(stats, outfile)

if __name__ == ""__main__"":
    main()
```']",2,[0],[],True,0,0,0,

