0,"Create a Python class called AlphabetCipher that contains methods for encoding and decoding messages using a simple substitution cipher based on the English alphabet. The class should have private fields for the alphabet, and include methods for encoding and decoding messages by shifting each letter in the message by a specified number of positions. Additionally, include a method to generate the encoded or decoded message as a string, along with an option to provide case sensitivity in the output.",338,,"[""```python
class AlphabetCipher:
    def __init__(self, shift=1, case_sensitive=True):
        self._alphabet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'
        self._shift = shift
        self._case_sensitive = case_sensitive

    def _get_position(self, char):
        if self._case_sensitive:
            return self._alphabet.find(char) if char.isalpha() else char
        else:
            lowercase = char.lower()
            uppercase = char.upper()
            return self._alphabet.find(lowercase) if lowercase.isalpha() else self._alphabet.find(uppercase) if uppercase.isalpha() else char

    def encode_message(self, message):
        encoded = []
        for char in message:
            position = (self._get_position(char) + self._shift) % 26
            encoded.append(self._alphabet[position])
        return ''.join(encoded)

    def decode_message(self, message):
        decoded = []
        for char in message:
            position = (self._get_position(char) - self._shift) % 26
            decoded.append(self._alphabet[position])
        return ''.join(decoded)
