0,"Create a Python script that processes configuration files located within a designated directory. It should analyze these files, compile summary statistics, and output the results to a user-specified file. The program must accept input through command line arguments: --help for displaying usage instructions, -d followed by directory_path to indicate the folder containing the configuration files, and -o followed by output_file_path to specify where the generated statistics will be saved. Employ standard library functions for file handling and data parsing, ensuring error notifications are provided for incorrect inputs or unavailability of files.",121,,"['```python
import argparse
import os
from statistics import mean, median, stdev
import sys

def process_file(file_path):
    try:
        with open(file_path, 'r') as file:
            data = list(map(float, file.read().split()))
            return mean(data), median(data), stdev(data)
    except FileNotFoundError:
        print(f""Error: File '{file_path}' not found."", file=sys.stderr)
        return None

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--help', action='store_true')
    parser.add_argument('-d', dest='directory_path', type=str, required=True)
    parser.add_argument('-o', dest='output_file_path', type=str, required=True)
    args = parser.parse_args()

    if args.help:
        print(__doc__)
        sys.exit(0)

    stats = []
    directory_path = os.path.abspath(args.directory_path)
    output_file_path = os.path.abspath(args.output_file_path)

    if not os.path.exists(directory_path):
        print(f""Error: Directory '{directory_path}' not found."", file=sys.stderr)
        sys.exit(1)

    for root, _, files in os.walk(directory_path):
        for file in files:
            if file.endswith('.cfg'):
                stats.append(process_file(os.path.join(root, file)))

    with open(output_file_path, 'w') as outfile:
        outfile.write(""Mean\tMedian\tStandard Deviation\n"")
        for stat in stats:
            if stat is not None:
                outfile.write('{}, {}, {}\n'.format(*stat))

if __name__ == ""__main__"":
    main()
```

This script uses the `argparse`, `os`, and `statistics` libraries to read command-line arguments, walk through a specified directory for configuration files, process them by calculating summary statistics, and output the results to a user-defined file. Error notifications are provided for incorrect inputs or unavailability of files.']",4,[0],[],True,0,0,0,

