0,"Create a Python-based web scraping tool that extracts and processes data from a target website. This tool should be able to generate JSON objects containing information about products, including their names, prices, and descriptions. The web scraping process should utilize BeautifulSoup and requests libraries for efficient data retrieval from HTML pages. Implement a mechanism that dynamically identifies product elements based on common patterns found in e-commerce websites, such as product divs or lists. The tool should include error handling to gracefully manage issues like network errors or unavailable content. Furthermore, incorporate a caching system to store previously scraped data, minimizing the need for repeated requests to the same URL and reducing load on the target website. Lastly, provide an API endpoint allowing users to query specific product details using unique identifiers, enabling real-time access to the scraped data without direct interaction with the web scraping code.",680,,"['```python
import json
import requests
from bs4 import BeautifulSoup
import re
import os
import time
import pickle

# Cache directory and file name
CACHE_DIR = ""cache""
if not os.path.exists(CACHE_DIR):
    os.makedirs(CACHE_DIR)
CACHE_FILE = os.path.join(CACHE_DIR, ""products.pkl"")

def get_html(url):
    try:
        response = requests.get(url)
        if response.status_code == 200:
            return response.text
        else:
            print(f""Error {response.status_code}: Failed to load URL."")
            return None
    except Exception as e:
        print(e)
        return None

def parse_products(html):
    soup = BeautifulSoup(html, ""html.parser"")

    # Customize the selector based on target website's structure
    product_containers = soup.select("".product-container"")  # Example class name for product divs

    products = []

    for container in product_containers:
        try:
            name = container.find(""h2"").text.strip()
            price = float(container.find(""span"", {""class"": ""price""}).text.strip().replace(""$"", """"))
            description = container.find(""p"", {""class"": ""description""}).text.strip()
        except Exception as e:
            print(e)
            continue

        product_data = {
            ""name"": name,
            ""price"": price,
            ""description"": description
        }
        products.append(product_data)

    return products

def cache_products(products):
    with open(CACHE_FILE, ""wb"") as f:
        pickle.dump(products, f)

def load_from_cache():
    if os.path.exists(CACHE_FILE):
        with open(CACHE_FILE, ""rb"") as f:
            return pickle.load(f)
    else:
        return None

def query_product(identifier):
    products = load_from_cache() or []
    if not products:
        print(""No data available in the cache."")
        return None

    for product in products:
        if str(identifier) == str(product[""id""]):
            return product

    print(""No product found with the given identifier."")
    return None

def main():
    url = ""https://example-ecommerce.com""  # Replace with the target website URL

    html = get_html(url)
    if not html:
        return

    products = parse_products(html)

    if products:
        cache_products(products)

    # API endpoint example using Flask framework (Replace with your preferred web framework or REST server)
    from flask import Flask, jsonify, request
    app = Flask(__name__)

    @app.route(""/api/v1/products/<int:id>"", methods=[""GET""])
    def get_product(id):
        return jsonify(query_product(id))

    if __name__ == ""__main__"":
        app.run(debug=True)

if __name__ == ""__main__"":
    main()
```']",401,[0],[],True,0,0,0,

