import random

def create_unique_sorted_array(length):
    array = [0] * length
    while any([x == y for x, y in zip(array, array[1:])] or not all([x <= y for x, y in zip(array, array[1:])])):
        for i in range(length):
            array[i] = random.randint(1, 100)
    return sorted(array)
