class TreeHelper:
    def calculate_preorder_traversal(self, tree):
        return self._preorder_traversal_helper(tree, [])

    def calculate_postorder_traversal(self, tree):
        return self._postorder_traversal_helper(tree, [])

    def _preorder_traversal_helper(self, tree, traversal_list):
        if tree is None:
            return traversal_list

        traversal_list.append(tree[0]) # visit the current node
        for left_child in self._get_left_children(tree[1:]):
            traversal_list = self._preorder_traversal_helper(left_child, traversal_list)

        for right_sibling in self._get_right_siblings(tree[1:]):
            traversal_list = self._preorder_traversal_helper(right_sibling, traversal_list)

        return traversal_list

    def _postorder_traversal_helper(self, tree, traversal_list):
        if tree is None:
            return traversal_list

        for left_child in self._get_left_children(tree[1:]):
            traversal_list = self._postorder_traversal_helper(left_child, traversal_list)

        for right_sibling in self._get_right_siblings(tree[1:]):
            traversal_list = self._postorder_traversal_helper(right_sibling, traversal_list)

        traversal_list.append(tree[0]) # visit the current node
        return traversal_list

    def _get_left_children(self, tree):
        left_children = []
        for node in tree:
            if node[1] is not None:
                left_children.append((node))
                break
            else:
                left_children.extend(self._get_left_children(tree[2 * (i + 1): 2 * (i + 2 + len(tree) // 2)]))
        return left_children

    def _get_right_siblings(self, tree):
        right_siblings = []
        for i in range(len(tree) - 1):
            if tree[i][1] is None:
                right_sibling = tree[i + 1]
                while right_sibling[1] is not None:
                    right_siblings.append((right_sibling))
                    right_sibling = right_sibling[2]
        return right_siblings
```

This implementation assumes that the input tree is represented as a list where each element at index 0 contains the value of the node, and the next `2 * num_children + 1` elements contain the children's positions in the same format. The first child's position starts from index 1, the second child's position starts from index (index of the first child + 3), and so on. If a child is absent, the corresponding position contains `None`.""]",0,[0],[],True,0,0,0,

