0,"Design and implement a class named ""GraphHelper"" with two methods. The first method, `calculate_breadth_first_search`, should take an input graph represented as an adjacency list, and return a list containing the nodes' values in breadth-first search order. The second method, `calculate_depth_first_search`, should do the same but for depth-first search order. Assume that the graph is a directed acyclic graph where each node can have multiple outgoing edges but no incoming edges from outside the specified nodes.",665,,"['```python
class GraphHelper:
    def calculate_breadth_first_search(self, adjacency_list):
        visited = set()
        queue = []
        order = []

        for node in adjacency_list:
            if node not in visited:
                visited.add(node)
                queue.append(node)

                while queue:
                    current = queue.pop(0)
                    order.append(current)

                    for neighbor in adjacency_list[current]:
                        if neighbor not in visited:
                            visited.add(neighbor)
                            queue.append(neighbor)

        return order

    def calculate_depth_first_search(self, adjacency_list):
        visited = set()
        stack = []
        order = []

        for node in adjacency_list:
            if node not in visited:
                visited.add(node)
                stack.append(node)

                while stack:
                    current = stack.pop()
                    order.append(current)

                    for neighbor in adjacency_list[current]:
                        if neighbor not in visited:
                            visited.add(neighbor)
                            stack.append(neighbor)

        return order
```']",0,[0],[],True,0,0,0,

