import os
import sys
import hashlib
import threading
from tqdm import tqdm
from typing import List

def validate_file_type(file_path):
    """"""Check if the file type is supported.""""""
    supported_extensions = ['.txt', '.jpg', '.png']
    _, ext = os.path.splitext(file_path)
    return ext in supported_extensions

def get_files(args=None):
    """"""Get list of files to be hashed from command line arguments or interactive input.""""""
    if args:
        files = args
    else:
        files = []
        print(""Enter file paths (type 'q' to quit)"")
        while True:
            path = input()
            if not path or path.lower() == ""q"":
                break
            if validate_file_type(path):
                files.append(path)
        args = files
    return args

def calculate_file_hash(file_path, chunk_size=65536, max_size=1073741824):  # 1 GB limit
    """"""Calculate MD5 hash of a given file.""""""
    if not os.path.exists(file_path) or os.path.getsize(file_path) > max_size:
        raise FileNotFoundError(f""File '{file_path}' does not exist or exceeds maximum size."")

    try:
        md5_hash = hashlib.md5()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(chunk_size), b''):
                md5_hash.update(chunk)
        return md5_hash.hexdigest()
    except Exception as e:
        raise IOError(f""An error occurred while hashing '{file_path}': {str(e)}"")

def hash_files(files):
    """"""Hash all files in parallel using threads.""""""
    results = []
    thread_pool = []

    for file in tqdm(files, desc=""Hashing files""):
        thread = threading.Thread(target=hash_single_file, args=(file,))
        thread.start()
        thread_pool.append(thread)

    for thread in thread_pool:
        thread.join()

    return results

def hash_single_file(file_path):
    try:
        result = calculate_file_hash(file_path)
    except Exception as e:
        print(f""Error hashing file {file_path}: {str(e)}"")
        result = None
    else:
        print(f""File {file_path} hashed successfully."")
    finally:
        return result

if __name__ == ""__main__"":
    args = sys.argv[1:]
    files = get_files(args)
    hashed_files = hash_files(files)
    print(""Hashes:"")
    for i, file in enumerate(files):
        if hashed_files[i]:
            print(f""{file}: {hashed_files[i]}"")
