0,"Create a program that manages a library's book collection. Implement a Book structure and a Library structure. Develop functions to add new books, remove existing books, and search for books by title or author. Integrate the functionality to update the book's status between 'available' and 'checked-out'. Also, include a method to generate dynamic filenames for saved library data based on the current date and time.",120,,"[' ```python
import datetime

class Book:
    def __init__(self, title, author, status):
        self.title = title
        self.author = author
        self.status = status

    def update_status(self, new_status):
        self.status = new_status

class Library:
    def __init__(self):
        self.books = {}

    def add_book(self, book):
        if book.title not in self.books:
            self.books[book.title] = []
        self.books[book.title].append(book)

    def remove_book(self, title):
        if title in self.books:
            del self.books[title]

    def search_by_title(self, title):
        return self.books.get(title, [])

    def search_by_author(self, author):
        for books in self.books.values():
            for book in books:
                if book.author == author:
                    yield book

    def update_book_status(self, title, new_status):
        for book in self.search_by_title(title):
            book.update_status(new_status)

    def save_library(self):
        now = datetime.datetime.now().strftime(""%Y%m%d-%H%M%S"")
        with open(f""library_{now}.txt"", ""w"") as file:
            for title, books in self.books.items():
                for book in books:
                    file.write(f""{book.title},{book.author},{book.status}\n"")
