Enhance the DNS resolution function to support IPv6 and custom DNS servers, with improved concurrency, resilience, error handling, caching, security features, locale-aware parsing, and advanced reverse lookup support.",590,,"['```python
import asyncio
import socket
import dns.resolver
import dns.query
import os
from functools import lru_cache
from threading import RLock

class CustomDNSResolver:
    def __init__(self, custom_servers=None):
        self.resolver = dns.resolver.Resolver(configure=False)
        if custom_servers:
            for server in custom_servers:
                self.resolver.add_nameserver(*server)

    @lru_cache(maxsize=128, typed=True)
    def query(self, domain, rrtype=dns.RRType.A):
        try:
            return [ip for ip, _ in self.resolver.query(domain, rrtype).response.answer]
        except Exception as e:
            print(f""Error resolving {domain}: {e}"")
            return []

    @staticmethod
    def is_ipv6(address):
        return address.startswith(""2001"") or address.startswith(""fe80"")

    @lru_cache(maxsize=128, typed=True)
    async def resolve_async(self, domain, rrtype=dns.RRType.A):
        tasks = []
        for server in self.resolver.nameservers:
            tasks.append(asyncio.create_task(self._resolve_async_at_server(domain, rrtype, server)))
        responses = await asyncio.gather(*tasks)
        combined_response = [ip for res in responses for ip in res]
        return list(set(combined_response))

    async def _resolve_async_at_server(self, domain, rrtype=dns.RRType.A, nameserver):
        query = dns.message.MakeQuery(domain, rrtype)
        query.edit_question(qname=domain, qtype=rrtype.to_string())
        transport = dns.transport.udp.UDPTransport((nameserver[0], nameserver[1]), timeout=5)
        response = await transport.get_response(query)
        return self._parse_response(domain, rrtype, response)

    @staticmethod
    def _parse_response(domain, rrtype=dns.RRType.A, response):
        if not response:
            return []
        try:
            answer = response.answersection.get(rrtype, [])
            return [ip._target for ip in answer]
        except dns.exception.NoAnswer:
            pass
        return []

    async def reverse_lookup(self, ip):
        if not socket.inet_pton(socket.AF_INET6, ip):
            ip = f""{ip}.ip6.arpa.""
        domain = ip[::-1] + "".in-addr.arpa.""
        try:
            return self.query(domain, dns.RRType.PTR)[0][::-1]
        except Exception as e:
            print(f""Error performing reverse lookup for {ip}: {e}"")
            return None

    def locale_aware_parse(self, hostname):
        parts = hostname.split(""."")
        if len(parts) > 1 and parts[-1].isdigit():
            # Assume it's an IPv4 address in numeric form
            try:
                ip = socket.inet_aton(hostname)
                return socker.inet_ntoa(ip)
            except Exception:
                pass
        return hostname

class CustomDNSClient:
    def __init__(self, resolver=None):
        if not resolver:
            self.resolver = CustomDNSResolver()
        else:
            self.resolver = CustomDNSResolver(custom_servers=resolver)

    async def resolve(self, hostname, rrtype=dns.RRType.A):
        return await self.resolver.resolve_async(hostname, rrtype)

    async def reverse_lookup(self, ip):
        return await self.resolver.reverse_lookup(ip)

    def parse(self, hostname):
        return self.resolver.locale_aware_parse(hostname)
